findings.codeql_raw_query:
/**
 * @name Code injection in setup.py
 * @description Checking for unsafe code execution patterns in setup.py
 * @kind problem
 * @problem.severity warning
 * @id py/setup-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SetupInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(CodeExecution ce).getCode()
  }
}

module SetupInjectionFlow = TaintTracking::Global<SetupInjectionConfig>;

from DataFlow::CallCfgNode call
where
  // Check if the call is in a setup.py file
  exists(File f |
    f.getBaseName() = "setup.py" and
    call.getEnclosingCallable().getLocation().getFile() = f
  ) and
  (
    // Check for dangerous built-in functions
    call = API::builtin("eval").getACall() or
    call = API::builtin("exec").getACall() or
    call = API::builtin("compile").getACall() or
    // Check for os.system
    call = API::moduleImport("os").getMember("system").getACall() or
    // Check for subprocess functions
    call = API::moduleImport("subprocess").getMember("call").getACall() or
    call = API::moduleImport("subprocess").getMember("check_call").getACall() or
    call = API::moduleImport("subprocess").getMember("check_output").getACall() or
    call = API::moduleImport("subprocess").getMember("run").getACall() or
    call = API::moduleImport("subprocess").getMember("Popen").getACall()
  )
select call, "Potentially unsafe code execution in setup.py"
